import 'package:family_veda/theme/app_theme.dart';
import 'package:flutter/material.dart';

/// Mandatory on every advisory surface (design.md).
///
/// Deliberately opaque rather than glass: this is the text that tells a patient
/// the system does not diagnose, and it has to stay legible over whatever the
/// ambient mesh happens to be doing behind it.
class ClinicalDisclaimer extends StatelessWidget {
  const ClinicalDisclaimer({super.key});

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final fill = isDark ? AppColors.surfaceDark : Colors.white;
    final ink = isDark ? AppColors.mutedDark : AppColors.muted;
    final border = isDark ? AppColors.borderDark : AppColors.border;
    final primary = isDark ? AppColors.primaryDark : AppColors.primary;

    return Semantics(
      label: 'Clinical safety disclaimer',
      child: Container(
        width: double.infinity,
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: fill,
          border: Border.all(color: border),
          borderRadius: const BorderRadius.all(Radius.circular(16)),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Icon(Icons.verified_user_outlined, size: 20, color: primary),
            const SizedBox(width: 12),
            Expanded(
              child: Text(
                'This is a clinical decision-support tool. It does not '
                'provide medical diagnosis. All guidance is reviewed and '
                'approved by a licensed doctor before you receive it. In an '
                'emergency, seek immediate in-person medical care.',
                style: TextStyle(fontSize: 13, height: 1.5, color: ink),
              ),
            ),
          ],
        ),
      ),
    );
  }
}
